/**
 * A line of evidence shown with an approval
 */
export type Evidence = {
    label: string;
    value: string;
    url?: string;
};

/**
 * 403 other than step_up_required: `forbidden` (a token without the scope, a member without the role, a credential the route does not admit), or a finer key (`email_link_other_browser`, `installation_not_yours`, `probe_not_yours`, `cutover_owner_required`, `self_approval_refused`: the server names the other approvers in `message` only, without the `others` of `SelfApprovalRefused`; `github_link_required`: a yes under a never-self-approve policy, on a pull request whose author linked no Ostrom person, from an answerer who linked no GitHub account)
 */
export type Forbidden = {
    /**
     * `ErrorDetail`, its `type` any 403 key but `step_up_required`
     */
    error: {
        type: 'forbidden' | 'email_link_other_browser' | 'installation_not_yours' | 'probe_not_yours' | 'cutover_owner_required' | 'self_approval_refused' | 'github_link_required';
        message: string;
    };
};

/**
 * A boundary action a gate covers
 */
export type GateAction = {
    class: string;
    label: string;
    patterns: Array<string>;
    /**
     * Repositories where the gate covers it. Absent or empty: every repository of the organization
     */
    repos?: Array<string>;
    tools?: Array<string>;
    /**
     * Catalogue only: the words of the class that a guessed gate matches
     */
    keywords?: Array<string>;
    /**
     * Catalogue only: the gate that covers the action in this repository; `null` when none does
     */
    gate?: GateRef | null;
};

/**
 * Asks for a gate (hook `PreToolUse`, CI check, MCP). A request in a closed session is refused with 409
 */
export type GateAskRequest = {
    sessionId?: string;
    runId?: string;
    repo?: string;
    realRepo?: string;
    class: string;
    tool?: string;
    command?: string;
    dev?: string;
    harnessVersion?: string;
    ci?: GateCi;
    diff?: string;
    push?: GatePush;
    pr?: GatePullRequest;
};

/**
 * The gates of a repository and the action classes they cover
 */
export type GateCatalog = {
    gates: Array<GateRef>;
    actions: Array<GateAction>;
    /**
     * What the hooks do when the server cannot be reached
     */
    failMode?: 'closed';
    /**
     * How long a hook waits for an answer before it gives up
     */
    waitSeconds?: number;
};

/**
 * CI context of a gate asked by a CI check
 */
export type GateCi = {
    sha?: string;
    pr?: string;
};

export type GateMode = 'enforced' | 'shadow' | 'ungated';

/**
 * A pull request merge, whichever path asked (the `gh pr merge` hook, the GitHub check): one request per pull request
 */
export type GatePullRequest = {
    number: string;
    sha: string;
    owner?: string;
};

/**
 * A push, read by the hook before it leaves: the remote and, for each ref, the commit it receives. The yes covers
 */
export type GatePush = {
    remote: string;
    refs: Array<GatePushRef>;
    force?: boolean;
};

/**
 * A ref of a push
 */
export type GatePushRef = {
    ref: string;
    sha: string;
};

/**
 * The gate of a workflow that covers an action, as the catalog resolves it. Its canonical form is part of the gate
 */
export type GateRef = {
    workflowId: string;
    workflowName: string;
    nodeId: string;
    label: string;
    approvers: Array<string>;
    status: WorkflowStatus;
    enforce: boolean;
    basis?: string;
    reason: string;
};

/**
 * A gate request: an agent (or a CI check) asks to perform a boundary action
 */
export type GateRequest = {
    id: string;
    approvalId?: string;
    sessionId?: string;
    runId?: string;
    repo?: string;
    realRepo?: string;
    dev: string;
    class: string;
    label: string;
    tool: string;
    command: string;
    key: string;
    gate: GateRef | null;
    mode: GateMode;
    status: GateStatus;
    at: string;
    decidedBy?: string;
    decidedAt?: string;
    receiptId?: string;
    harnessVersion?: string;
    ci?: GateCi;
    devVerified?: boolean;
    pr?: GatePullRequest;
    askedVia?: Array<string>;
    selfApproved?: boolean;
    push?: GatePush;
};

/**
 * A gate request with its approval and its receipt
 */
export type GateResponse = {
    gate: GateRequest;
    approval?: Approval;
    receipt?: Receipt;
    waitingFor?: Array<string>;
};

export type GateStatus = 'pending' | 'approved' | 'rejected' | 'shadow' | 'ungated' | 'consumed';

export type GitHubConnection = 'github-app' | 'gh-token';

/**
 * The governance write a confirmation holds: the operation that opened it
 */
export type GovernanceChangeKind = 'rules.create' | 'rules.update' | 'rules.delete' | 'rules.bulk' | 'gates.policy' | 'models.policy' | 'workflows.create' | 'workflows.save' | 'workflows.delete';

/**
 * A governance write made with a CLI token, held until an owner or an admin confirms it on the console. `before` and `after` are what the change replaces and what it writes, as the read routes show them (JSON null for nothing: a creation has no `before`, a deletion no `after`)
 */
export type GovernanceConfirmation = {
    id: string;
    kind: GovernanceChangeKind;
    status: GovernanceConfirmationStatus;
    /**
     * The method of the write, such as `PUT`
     */
    method: string;
    /**
     * The path of the write, such as `/api/v1/gates/policy`
     */
    path: string;
    /**
     * The governance scope the write uses (`policy:write`, `harness:write`, `gates:policy`)
     */
    scope: string;
    /**
     * One line saying what the change does
     */
    summary: string;
    /**
     * What the change replaces, as the read routes show it; JSON null for nothing (a creation)
     */
    before: unknown;
    /**
     * What the change writes, as the read routes show it; JSON null for nothing (a deletion)
     */
    after: unknown;
    requestedBy: GovernanceConfirmationPerson;
    /**
     * The person's token that asked: `admin` when it holds a governance scope (`ostrom login --admin`), `device` otherwise (`ostrom login`, a personal token). An agent, a runner or a service key never opens one
     */
    credential: 'admin' | 'device';
    createdAt: string;
    expiresAt: string;
    /**
     * Who confirmed or refused it; a confirmed change is their signed decision
     */
    answeredBy?: GovernanceConfirmationPerson;
    answeredAt?: string;
    /**
     * What the write returned once confirmed (absent when it returns nothing, as a deletion)
     */
    result?: unknown;
    /**
     * Why a confirmed change was not written (`failed`)
     */
    error?: ErrorDetail;
};

export type GovernanceConfirmationAnswer = 'confirm' | 'refuse';

export type GovernanceConfirmationAnswerRequest = {
    answer: GovernanceConfirmationAnswer;
};

/**
 * The 202 of a governance write made with a CLI token: nothing was written. An owner or an admin confirms it at `confirmUrl` before `expiresAt` (15 minutes); the CLI waits on `getGovernanceConfirmation`. The same change asked again by the same person while it waits answers the same confirmation
 */
export type GovernanceConfirmationPending = {
    confirmationId: string;
    /**
     * The absolute URL of the console page that confirms it (`<console>/confirm/<id>`)
     */
    confirmUrl: string;
    expiresAt: string;
};

/**
 * A member who asked for or answered a confirmation
 */
export type GovernanceConfirmationPerson = {
    memberId: string;
    /**
     * Their GitHub login, when known
     */
    login?: string;
    name?: string;
};

/**
 * pending until answered; confirmed, refused, expired (15 minutes without an answer), or failed (confirmed, but the write was refused: see `error`). The confirmation is closed before the write is made: a server stopped between the two leaves it confirmed without the write, and the change is then asked again
 */
export type GovernanceConfirmationStatus = 'pending' | 'confirmed' | 'refused' | 'expired' | 'failed';

/**
 * A group of members sharing subscriptions
 */
export type Group = {
    id: string;
    name: string;
    members: Array<string>;
    accounts: Array<string>;
    /**
     * The members paused now, by login, and the end of their pause
     */
    paused?: Array<{
        login: string;
        until: string;
    }>;
};

/**
 * Liveness and the result of each check
 */
export type Health = {
    status: string;
    version: string;
    checks: {
        [key: string]: string;
    };
};

/**
 * A hook delivered to developers outside session packages
 */
export type Hook = {
    name: string;
    version: string;
    pinned: boolean;
    assignedTo: Array<string>;
};

/**
 * One line of an import report
 */
export type ImportItem = {
    /**
     * Clients keep an unknown kind as UNKNOWN
     */
    kind: 'setting' | 'secret' | 'server' | 'policy' | 'assignment' | 'account';
    name: string;
    /**
     * `revive_at_cutover`: a shared account waiting for a reconnection, left so while TeamCode runs; the cutover run revives it.
     */
    action: 'planned' | 'created' | 'updated' | 'unchanged' | 'skipped' | 'revive_at_cutover';
    /**
     * Why it was skipped, or why a `revive_at_cutover` line waits for the cutover run
     */
    reason?: string;
};

/**
 * What an import did; a second run reports everything unchanged
 */
export type ImportReport = {
    items: Array<ImportItem>;
    created: number;
    updated: number;
    unchanged: number;
    skipped: number;
    /**
     * Shared accounts left waiting for a reconnection until the cutover run (`revive_at_cutover` lines)
     */
    reviveAtCutover: number;
};

/**
 * Where a model is served from
 */
export type InferenceRoute = {
    id: string;
    model: string;
    provider: string;
    account?: string;
    priority: number;
};

/**
 * The instance as clients see it
 */
export type Instance = {
    id: string;
    /**
     * The server version
     */
    version: string;
    createdAt: string;
    signingKey: InstanceSigningKey;
};

/**
 * A key the instance signs with
 */
export type InstanceSigningKey = {
    keyId: string;
    /**
     * `ed25519`
     */
    algorithm: string;
    /**
     * PEM (SPKI)
     */
    publicKeyPem: string;
    firstSeenAt: string;
};

/**
 * A live invitation
 */
export type Invitation = {
    id: string;
    /**
     * Null for a link
     */
    email: string | null;
    /**
     * `owner`, `admin`, `member`, `approver` or `billing`
     */
    role: string;
    createdAt: string;
    expiresAt: string;
    maxUses: number | null;
    uses: number;
};

/**
 * A new invitation link: the only time its URL is shown
 */
export type InvitationLink = {
    invitation: Invitation;
    url: string;
};

/**
 * A new invitation link
 */
export type InvitationLinkCreate = {
    /**
     * `member` by default
     */
    role?: string;
    /**
     * How many people it can bring in, 1 to 100 (10 by default)
     */
    maxUses?: number;
};

/**
 * The live invitations
 */
export type InvitationList = {
    items: Array<Invitation>;
};

/**
 * What an invitation leads to
 */
export type InvitationPreview = {
    orgName: string;
    orgSlug: string;
    /**
     * `owner`, `admin`, `member`, `approver` or `billing`
     */
    role: string;
    email: string | null;
    expiresAt: string;
};

/**
 * An invitation link's token, sent in the body
 */
export type InvitationToken = {
    token: string;
};

/**
 * A JSON-RPC 2.0 error, as the MCP relay answers it
 */
export type JsonRpcError = {
    jsonrpc: '2.0';
    /**
     * The request's id; null when it could not be read
     */
    id?: string | number | null;
    error: {
        code: number;
        message: string;
    };
};

/**
 * The consent page of a started link
 */
export type LinkStarted = {
    authorizationUrl: string;
};

/**
 * One test on a tool call's arguments
 */
export type McpArgumentCondition = {
    /**
     * A dotted path into the arguments (`query`, `options.database`, `items.0.id`)
     */
    path: string;
    /**
     * Answers carry these values; requests may use any case. MATCHES is a case-insensitive regular expression that may not repeat a repeated group (`(a+)+`) nor refer back to a group, and an argument longer than 8192 characters counts as matching (fail closed)
     */
    operator: 'EQUALS' | 'NOT_EQUALS' | 'MATCHES' | 'PREFIX' | 'CONTAINS' | 'EXISTS' | 'ABSENT';
    /**
     * The operand, unused for EXISTS and ABSENT
     */
    value?: string;
};

/**
 * The argument policies of a relayed server, at most 64, so always one page
 */
export type McpArgumentPolicies = {
    policies: Array<McpArgumentPolicy>;
    /**
     * Reserved for paging; always absent today
     */
    next?: string;
};

/**
 * A rule on a tool's arguments, checked on every call before it reaches the upstream server
 */
export type McpArgumentPolicy = {
    id: string;
    tool: string;
    conditions: Array<McpArgumentCondition>;
    /**
     * DENY refuses the call; REQUIRE_APPROVAL holds it until a human approves it
     */
    effect: 'DENY' | 'REQUIRE_APPROVAL';
    /**
     * What the agent is told
     */
    message: string;
    createdAt: string;
};

/**
 * A new argument policy; every condition must hold (none means every call of the tool)
 */
export type McpArgumentPolicyRequest = {
    tool: string;
    conditions?: Array<McpArgumentCondition>;
    /**
     * Any case is accepted; answers carry the upper-case value
     */
    effect: 'DENY' | 'REQUIRE_APPROVAL';
    message: string;
};

/**
 * Who reaches a relayed server and which of its tools. A member's own assignment replaces the one for every member (`all`) for that member, it never adds to it; removing `all` leaves members' own assignments
 */
export type McpAssignment = {
    server: string;
    /**
     * The member's id (`Member.id`); absent for every member of the org
     */
    member?: string;
    /**
     * The allowlist; absent for every tool, empty for none
     */
    tools?: Array<string>;
    /**
     * The member's personal secret used as credential, for a per-member server
     */
    credentialSecret?: string;
    assignedAt: string;
};

/**
 * An assignment; hiding a tool is not the boundary, every call is checked again
 */
export type McpAssignmentRequest = {
    /**
     * The allowlist; absent for every tool, empty for none (send `[]`, never drop it)
     */
    tools?: Array<string>;
    /**
     * The name of one of the member's personal secrets, only for a per-member server and one member (400 with `all`)
     */
    credentialSecret?: string;
};

/**
 * The assignments of a server, one per member and one for `all` at most, so always one page
 */
export type McpAssignmentsPage = {
    items: Array<McpAssignment>;
    /**
     * Reserved for paging; always absent today
     */
    next?: string;
};

/**
 * A relayed MCP call
 */
export type McpCall = {
    id: string;
    at: string;
    server: string;
    tool: string;
    dev: string;
    sessionId?: string;
    /**
     * The launch whose agent token made the call (`POST /launches`), set by the server from the token; absent for a person's own credential. The launch may differ from the one of `sessionId`
     */
    launchId?: string;
    durationMs?: number;
    ok: boolean;
    /**
     * `OK`, `DENIED`, `UPSTREAM_ERROR`…
     */
    outcome?: string;
    /**
     * The upstream answer's size
     */
    responseBytes?: number;
    /**
     * The argument policy that refused the call
     */
    policyId?: string;
};

/**
 * An MCP server relayed by Ostrom; its credentials stay on the server
 */
export type McpServer = {
    /**
     * 1 to 64 characters; `servers`, `settings`, `calls` and `usage` are reserved (they are paths of this API)
     */
    name: string;
    /**
     * The upstream URL of an HTTP server; absent for a stdio server. In answers, a stdio server reads `stdio:<launcher>:<package>`, and a member's list (`mine=true`) gives the relay path, never the upstream
     */
    url?: string;
    /**
     * http, sse or stdio
     */
    transport: string;
    /**
     * The org secrets the server uses, in an admin's list only
     */
    secretNames?: Array<string>;
    tools?: Array<string>;
    enabled: boolean;
    scope: string;
    /**
     * The name the agent sees (`<agentPrefix>-<name>`), in a member's list
     */
    readonly agentName?: string;
    /**
     * The relay endpoint, in a member's list
     */
    readonly path?: string;
    /**
     * The header carrying the credential, when not `Authorization: Bearer`
     */
    credentialHeader?: string;
    stdio?: McpStdioSpec;
    /**
     * Bumped at each change
     */
    readonly version?: number;
    readonly createdAt?: string;
};

/**
 * How the gateway reaches model providers for the org (bring your own key)
 */
export type InferenceSettings = {
    /**
     * Name of the org secret holding an Anthropic API key, used when no shared Claude account serves
     */
    anthropicKeySecret?: string;
    /**
     * Name of the org secret holding an OpenAI API key
     */
    openaiKeySecret?: string;
    /**
     * Name of the org secret holding an OpenRouter key (models named `vendor/model`)
     */
    openrouterKeySecret?: string;
    /**
     * Whether members' shared subscription accounts serve before the org's keys
     */
    useSharedAccounts?: boolean;
};

/**
 * How agents see relayed servers
 */
export type McpSettings = {
    /**
     * Tools are `mcp__<agentPrefix>-<server>__<tool>`; 1 to 32 characters of a-z 0-9 _ -, default `ostrom`
     */
    agentPrefix: string;
};

/**
 * A server run by the MCP host from a pinned package
 */
export type McpStdioSpec = {
    launcher: 'npm' | 'pypi';
    /**
     * name@1.2.3 (npm) or name==1.2.3 (PyPI)
     */
    packageName: string;
    args?: Array<string>;
    env?: {
        [key: string]: string;
    };
    /**
     * Variable name to the name of the org secret injected by the server
     */
    secretEnv?: {
        [key: string]: string;
    };
};

/**
 * The caller
 */
export type Me = {
    dev: Dev;
    member?: Member;
    organization?: Organization;
    capabilities: Array<string>;
    /**
     * For a browser session, the token to send in `X-CSRF-Token` on state-changing requests
     */
    csrfToken?: string;
};

/**
 * A member of an organization
 */
export type Member = {
    /**
     * The member's id, stable across their tokens and sessions. Routes that take a member id (`memberId` of `/api/v1/artifacts/{id}/members/{memberId}`, `member` of the relayed servers, `memberMap` of the TeamCode import) take this one; routes under `/api/v1/members/{login}` take the login
     */
    id: string;
    login: string;
    name?: string;
    avatarUrl: string;
    email?: string;
    teams?: Array<string>;
    role: MemberRole;
    slackUserId?: string;
    discordUserId?: string;
};

/**
 * One person to invite into the organization
 */
export type MemberInvite = {
    /**
     * Their GitHub login
     */
    login: string;
    /**
     * Their role once they join; `member` when absent. `owner` and `invited` are refused
     */
    role?: MemberRole;
    /**
     * The slug of a team they join; none when absent
     */
    team?: string;
};

/**
 * One of the caller's organizations, to choose the one `Ostrom-Org` names
 */
export type MyOrganization = {
    id: string;
    slug: string;
    name: string;
    /**
     * The picture of the linked GitHub organization, empty when none
     */
    avatarUrl: string;
    /**
     * The caller's role there
     */
    role: MemberRole;
};

/**
 * The signed-in person's account
 */
export type Account = {
    id: string;
    /**
     * The handle, unique on the instance
     */
    login: string;
    displayName: string;
    /**
     * The main e-mail; absent when there is none
     */
    primaryEmail?: string;
    /**
     * The picture; absent when there is none
     */
    avatarUrl?: string;
    createdAt: string;
    emails: Array<AccountEmail>;
    /**
     * How the person signs in: `github`, `google`, `email` or `oidc:<connection>`
     */
    providers: Array<string>;
};

